function loadLocale(name) {
    var oldLocale = null,
        aliasedRequire;
    if (
        locales[name] === undefined &&
        typeof module !== 'undefined' &&
        module &&
        module.exports
    ) {
        try {
            oldLocale = globalLocale._abbr;
            aliasedRequire = require;
            aliasedRequire('./locale/' + name);
            getSetGlobalLocale(oldLocale);
        } catch (e) {
            locales[name] = null;
        }
    }
    return locales[name];
}

